;(() => {
  /* 卡塞尔启动动画 —— DSH 浏览器半插件（shell.overlay）

     要点：宿主的 shell.overlay 是带自身层叠上下文的浮层容器，宿主自己的弹窗
     （例如「预览版说明」）渲染在更上层，只靠 z-index 盖不住。所以这里只在插槽
     里占个空位，真正的动画容器用原生 DOM 挂到 document.body —— 成为 body 的
     直接子元素，z-index 才能和宿主的所有层级正面比较。

     动画播完（金色「欢迎来到卡塞尔」）后 iframe 发来 kassel-boot-go，
     本组件淡出并移除容器。 */
  function makeFactory() {
    return (require) => {
      const module = { exports: {} };
      const react = require("react");
      const { createElement: h, useEffect } = react;

      const B64 = "";

      let BOOT_HTML = "";
      try {
        const bytes = Uint8Array.from(atob(B64), (c) => c.charCodeAt(0));
        BOOT_HTML = new TextDecoder("utf-8").decode(bytes);
      } catch (e) {
        console.error("[kassel-boot] 动画资源解码失败", e);
      }

      const Z = 2147483600;

      function KasselBoot() {
        useEffect(() => {
          if (!BOOT_HTML) return;

          const host = document.createElement("div");
          host.setAttribute("data-kassel-boot", "");
          host.style.cssText = [
            "position:fixed",
            "inset:0",
            "margin:0",
            "padding:0",
            "z-index:" + Z,
            "background:#0A1118",
            "opacity:1",
            "transition:opacity .65s ease",
            "pointer-events:auto",
          ].join(";");

          const frame = document.createElement("iframe");
          frame.title = "Kassel Boot";
          frame.setAttribute("frameborder", "0");
          frame.style.cssText =
            "width:100%;height:100%;border:0;display:block;background:#0A1118";
          frame.srcdoc = BOOT_HTML;
          host.appendChild(frame);

          let removed = false;
          const remove = () => {
            removed = true;
            if (host.parentNode) host.parentNode.removeChild(host);
          };

          const onMsg = (e) => {
            const d = e && e.data;
            if (!d || typeof d !== "object") return;
            if (d.type === "kassel-boot-go" && !removed) {
              host.style.opacity = "0";
              host.style.pointerEvents = "none";
              setTimeout(remove, 700);
            }
          };

          document.body.appendChild(host);
          window.addEventListener("message", onMsg);

          return () => {
            window.removeEventListener("message", onMsg);
            if (host.parentNode) host.parentNode.removeChild(host);
          };
        }, []);

        return null;
      }

      const name = "kassel-boot";
      const inject = ["slots"];

      function apply(ctx) {
        ctx.slots.inject("shell.overlay", function* () {
          yield ctx.slots.register(
            { name: "shell.overlay", id: "kassel-boot", order: -1000 },
            () => h(KasselBoot)
          );
        });
      }

      module.exports = { apply, inject, name };
      return module.exports;
    };
  }
  window.__ModuleLoader__.load({ id: "dsh-kassel-boot", factory: makeFactory() });
})();
